export async function POST(request: NextRequest, { params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;

  const workspace = await prisma.workspace.findUnique({ where: { slug } });
  if (!workspace) {
    return NextResponse.json({ error: "Unknown workspace" }, { status: 404 });
  }
  if (!workspace.slackSigningSecret) {
    return NextResponse.json(
      { error: "Slack is not configured for this workspace yet" },
      { status: 400 }
    );
  }

  const rawBody = await request.text();
  const valid = verifySlackSignature({
    signingSecret: workspace.slackSigningSecret,
    timestamp: request.headers.get("x-slack-request-timestamp"),
    signature: request.headers.get("x-slack-signature"),
    rawBody,
  });

  if (!valid) {
    return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
  }

  let payload: SlackEventCallback;
  try {
    payload = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  // Slack's one-time handshake when you save the Request URL.
  if (payload.type === "url_verification") {
    return NextResponse.json({ challenge: payload.challenge });
  }

  if (payload.type === "event_callback" && payload.event?.type === "message") {
    const text = payload.event.text ?? "";
    // Ignore the bot's own messages and anything that isn't our command,
    // but still log the event so admins can see traffic is arriving.
    const isBot = Boolean(payload.event.bot_id);
    const command = !isBot ? parsePulseCommand(text) : null;

    let createdFeedbackId: string | null = null;

    if (command) {
      const feedback = await prisma.feedback.create({
        data: {
          title: command.title.slice(0, 140),
          body: command.title,
          workspaceId: workspace.id,
          source: "SLACK",
          externalAuthorName: payload.event.username ?? payload.event.user ?? "Slack user",
        },
      });
      createdFeedbackId = feedback.id;
    }

    await prisma.slackEventLog.create({
      data: {
        workspaceId: workspace.id,
        eventType: payload.event.type,
        text: text.slice(0, 500),
        createdFeedbackId,
      },
    });
  }

  return NextResponse.json({ ok: true });
}

