const timestamp = Math.floor(Date.now() / 1000).toString();
const slackEventPayload = {
  type: "event_callback",
  event: {
    type: "message",
    text: "/pulse feedback Export is slow\nIt takes 2 minutes for 10k rows",
    user: "U123456",
  },
};
const rawBody = JSON.stringify(slackEventPayload);
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);

class TestRequest {
  headersMap = new Map([
    ["x-slack-request-timestamp", timestamp],
    ["x-slack-signature", signature],
  ]);
  async text() { return rawBody; }
  get headers() {
    return {
      get: (key) => this.headersMap.get(key.toLowerCase()) || null,
      has: (key) => this.headersMap.has(key.toLowerCase()),
      keys: () => this.headersMap.keys(),
      entries: () => this.headersMap.entries(),
      forEach: (cb) => this.headersMap.forEach(cb),
    };
  }
}

const request = new TestRequest();

arranged();

const response = await POST(request as any, { params: Promise.resolve({ slug: workspace.slug }) });
const json = await response.json();

const feedbacks = await prisma.feedback.findMany({ where: { workspaceId: workspace.id } });
const feedbackCount = feedbacks.length;

record("response", json);
record("feedbackCount", feedbackCount);
harm_observed(feedbackCount === 0, "no feedback created despite valid /pulse feedback command");

